def wrap(title,desc,body,active='/',slug=''):
 canonical=site_url+('/'+slug if slug else '/')
 encoded_title=escape(title);encoded_desc=escape(desc,quote=True)
 # Retain the existing clean URL structure, and make social previews route-specific.
 hero=not slug and title.startswith('Joyce Ndehi & Company Advocates |')
 preload='<link rel="preload" as="image" href="/assets/images/legal-hero.jpg" fetchpriority="high">' if hero else ''
