 web_site={"@type":"WebSite","@id":site_url+"/#website","url":site_url+"/","name":name,"publisher":{"@id":site_url+"/#firm"},"inLanguage":"en-KE"}
 web_page={"@type":"WebPage","@id":canonical+"#webpage","url":canonical,"name":title,"description":desc,"isPartOf":{"@id":site_url+"/#website"},"about":{"@id":site_url+"/#firm"},"inLanguage":"en-KE","primaryImageOfPage":{"@type":"ImageObject","url":site_image,"width":1200,"height":630}}
 graph=[organization,web_site,web_page]
 if slug and not error_page:
  graph.append({"@type":"BreadcrumbList","@id":canonical+"#breadcrumbs","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":site_url+"/"},{"@type":"ListItem","position":2,"name":page_labels.get(slug,title.split('|')[0].strip()),"item":canonical}]})
 if error_page:
  # Error content is never a search result, regardless of its HTTP response status.
  robots='<meta name="robots" content="noindex,follow">'
 else: robots='<meta name="robots" content="index,follow,max-image-preview:large">'
 structured_data=json.dumps({"@context":"https://schema.org","@graph":graph},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
 return f'''<!doctype html><html lang="en-KE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#cf0000"><title>{encoded_title}</title><meta name="description" content="{encoded_desc}">{robots}<link rel="canonical" href="{canonical}"><link rel="icon" type="image/png" sizes="192x192" href="/images/icon-192.png"><link rel="apple-touch-icon" href="/images/icon-192.png"><link rel="manifest" href="/site.webmanifest"><meta property="og:type" content="website"><meta property="og:site_name" content="{name}"><meta property="og:locale" content="en_KE"><meta property="og:title" content="{encoded_title}"><meta property="og:description" content="{encoded_desc}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{site_image}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Joyce Ndehi &amp; Company Advocates, Kiambu"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{encoded_title}"><meta name="twitter:description" content="{encoded_desc}"><meta name="twitter:image" content="{site_image}">{preload}<link rel="stylesheet" href="/assets/css/site.css?v=10"><script type="application/ld+json">{structured_data}</script></head><body><a class="skip-link" href="#main-content">Skip to content</a>{header(active)}<main id="main-content">{body}</main>{footer()}</body></html>'''

